const money=value=>new Intl.NumberFormat('th-TH').format((Number(value)||0)/100)+' บาท';
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const validSlug=value=>/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(value)&&value.length>=3&&value.length<=50;
const safePublicUrl=value=>{try{const url=new URL(value);return url.protocol==='https:'&&/^[a-z0-9.-]+$/.test(url.hostname)&&url.pathname.split('/').length===2&&validSlug(url.pathname.slice(1))?url.href:''}catch{return''}};
