document.addEventListener('click',event=>{const clear=event.target.closest('[data-clear-media]');if(!clear)return;const field=clear.closest('.vpage-media-field'),url=field?.querySelector('[data-media-url]'),file=field?.querySelector('[data-media-file]');if(!url)return;field.dataset.mediaRevision=String((Number(field.dataset.mediaRevision)||0)+1);url.value='';delete url.dataset.previewUrl;if(file?.dataset.objectUrl)URL.revokeObjectURL(file.dataset.objectUrl);if(file){file.value='';delete file.dataset.objectUrl}field.querySelector('[data-media-status]').textContent='ล้างรูปจากช่องนี้แล้ว กรุณาเซฟร่างหรือบันทึกชุด';refreshTemplate(field.closest('[data-content-set],[data-create-content-set]'));markDraftDirty()});

async function loadOffer(){const response=await fetch('/api/vpage/offer');const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'โหลดแพ็กเกจ Vpage ไม่สำเร็จ');offer=data.item;price.textContent=money(offer.price)+' / 1 เครดิต';buy.disabled=false}
async function loadAccount(){try{const response=await fetch('/api/auth/me',{cache:'no-store'});if(!response.ok)return;const data=await response.json();currentUser=data.user;if(['boss','admin'].includes(currentUser?.role))document.querySelector('#vpageAdminLink').hidden=false;await Promise.all([loadCredits(true),loadDomains(),loadPages(),loadOwnerAssets()]);await loadDraft()}finally{createForm.inert=false}}
async function loadDomains(){const response=await fetch('/api/vpage/domains',{cache:'no-store'}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'โหลดโดเมนไม่สำเร็จ');domains=data.items||[];domainSelect.innerHTML=domains.map(item=>`<option value="${esc(item.id)}" data-hostname="${esc(item.hostname)}">${esc(item.hostname)}</option>`).join('')||'<option value="">ยังไม่มีโดเมนที่เปิดใช้</option>';domainSelect.disabled=!domains.length;updatePreview();updateCreateButton()}
async function loadPages(){const response=await fetch('/api/vpage/pages?limit=24',{cache:'no-store'}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'โหลดเซลเพจไม่สำเร็จ');pages.innerHTML=(data.items||[]).map(item=>{const publicUrl=safePublicUrl(item.public_url),repairable=['provisioning','repair_required'].includes(item.status),lifecycle=item.lifecycle_status||item.status,renewalPending=['held','remote_committed','repair_required'].includes(item.renewal_state),editable=lifecycle==='active',renewable=['expired','suspended'].includes(lifecycle),statusText=renewalPending?'กำลังตรวจสอบการต่ออายุ':lifecycle==='active'?'เปิดใช้งาน':lifecycle==='expired'?'หมดอายุ':lifecycle==='suspended'?'ระงับใช้งาน':repairable?'กำลังตรวจสอบผล':item.status==='failed'?'สร้างไม่สำเร็จ':esc(lifecycle),expiry=item.expires_at?new Date(item.expires_at).toLocaleDateString('th-TH'):'';return`<article class="vpage-page-row"><div><b>${esc(item.display_name)}</b>${publicUrl?`<a href="${esc(publicUrl)}" target="_blank" rel="noopener">${esc(publicUrl)}</a>`:'<small>กำลังตรวจสอบ URL</small>'}${expiry?`<small>วันสิ้นสุดบริการ ${esc(expiry)}</small>`:''}</div><div class="vpage-page-state"><span data-status="${esc(lifecycle)}">${statusText}</span>${editable?`<button type="button" data-edit-page="${esc(item.id)}">จัดการเนื้อหา</button>`:''}${renewalPending?`<button type="button" data-renew-page="${esc(item.id)}" data-renew-repair="true">ตรวจสอบการต่ออายุ</button>`:renewable?`<button type="button" data-renew-page="${esc(item.id)}">ใช้ 1 เครดิตต่ออายุ 30 วัน</button>`:''}${repairable?`<button type="button" data-repair-page="${esc(item.id)}">ตรวจสอบและดำเนินการต่อ</button>`:''}</div></article>`}).join('')||'<p>ยังไม่มีเซลเพจ</p>'}
async function loadCredits(reset=false){const url='/api/vpage/credits?limit=24'+(!reset&&nextCursor?`&cursor=${encodeURIComponent(nextCursor)}`:'');const response=await fetch(url,{cache:'no-store'});if(response.status===401)return;const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'โหลดเครดิตไม่สำเร็จ');balance.textContent=String(data.balance||0);const markup=(data.items||[]).map(item=>`<div class="vpage-credit-row"><div><b>เครดิต #${Number(item.id)}</b><small>ออเดอร์ ${esc(item.order_no)} · ${new Date(item.granted_at+'Z').toLocaleString('th-TH')}</small></div><span>${item.status==='available'?'พร้อมใช้':item.status==='provisioning'?'กำลังตรวจสอบการสร้าง':item.status==='renewing'?'กำลังตรวจสอบการต่ออายุ':'ใช้แล้ว'}</span></div>`).join('');credits.innerHTML=reset?(markup||'<p>ยังไม่มีเครดิต Vpage</p>'):credits.innerHTML+markup;nextCursor=data.pagination?.next_cursor||null;loadMore.hidden=!data.pagination?.has_more;updateCreateButton()}
function updatePreview(){slugInput.value=slugInput.value.replace(/[A-Z]/g,char=>char.toLowerCase());const hostname=domainSelect.selectedOptions[0]?.dataset.hostname||'smartlinkpage.com',slug=slugInput.value;preview.textContent=`https://${hostname}/${validSlug(slug)?slug:'your-slug'}`}
function updateCreateButton(){createButton.disabled=!currentUser||!domains.length||Number(balance.textContent||0)<1||!validSlug(slugInput.value)||!document.querySelector('#vpageDisplayName').value.trim()||availability.dataset.available!=='true'}
async function checkAvailability(){availabilityController?.abort();const domainId=domainSelect.value,slug=slugInput.value;availability.textContent='';if(!domainId||!validSlug(slug)){updateCreateButton();return}availabilityController=new AbortController();try{const response=await fetch(`/api/vpage/availability?domain_id=${encodeURIComponent(domainId)}&slug=${encodeURIComponent(slug)}`,{cache:'no-store',signal:availabilityController.signal}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'ตรวจสอบ slug ไม่สำเร็จ');availability.textContent=data.available?'URL นี้พร้อมใช้งาน':'URL นี้ถูกใช้แล้ว';availability.dataset.available=String(Boolean(data.available));createButton.disabled=!data.available||Number(balance.textContent||0)<1}catch(error){if(error.name!=='AbortError'){availability.textContent=error.message;createButton.disabled=true}}}

const mediaField=(label,input)=>`<div class="vpage-media-field"><label>${label}${input}</label><label class="vpage-media-upload">เลือกไฟล์ JPG, PNG หรือ WEBP (ไม่เกิน 5 MB)<input data-media-file type="file" accept="image/jpeg,image/png,image/webp"></label><button type="button" data-upload-media>อัปโหลดรูปนี้</button><small data-media-status>เลือกไฟล์เพื่อดูตัวอย่างในเครื่องก่อนอัปโหลด</small></div>`;
const createMediaField=(label,input)=>{const safeInput=input.replace('data-media-url type="url"','data-media-url type="hidden"'),selected=safeInput.match(/vpm_[a-f0-9]{32}/)?.[0]||'';return`<div class="vpage-media-field"><label>${label}${safeInput}</label><label class="vpage-media-upload">เลือกไฟล์ JPG, PNG หรือ WEBP (ไม่เกิน 5 MiB, กว้าง/สูงไม่เกิน 4096 พิกเซล)<input data-media-file type="file" accept="image/jpeg,image/png,image/webp"></label><button type="button" data-upload-media>อัปโหลดรูปนี้</button><label>รูปที่อัปโหลดไว้<select data-owner-assets><option value="">เลือกรูปจากคลัง</option>${ownerAssets.map(item=>`<option value="${esc(item.id)}"${selected===item.id?' selected':''}>${item.state==='ready'?'พร้อมใช้':'รอคัดลอก'} · ${item.width}×${item.height} · ${esc(item.id.slice(-8))}</option>`).join('')}</select></label><div class="vpage-media-actions"><button type="button" data-use-media>ใช้รูปที่เลือก</button><button type="button" data-clear-media>ล้างรูปจากช่องนี้</button><button type="button" data-delete-media>ลบรูปที่เลือก</button></div><small data-media-status>เลือกไฟล์เพื่อดูตัวอย่างในเครื่องก่อนอัปโหลด</small></div>`};
function refreshOwnerAssetChoices(){for(const select of document.querySelectorAll('[data-owner-assets]')){const current=select.value||select.closest('.vpage-media-field').querySelector('[data-media-url]')?.value.split('/').at(-1)||'';select.innerHTML='<option value="">เลือกรูปจากคลัง</option>'+ownerAssets.map(item=>`<option value="${esc(item.id)}">${item.state==='ready'?'พร้อมใช้':'รอคัดลอก'} · ${item.width}×${item.height} · ${esc(item.id.slice(-8))}</option>`).join('');if(ownerAssets.some(item=>item.id===current))select.value=current}}
async function loadOwnerAssets(force=false){if(ownerAssetsPending){await ownerAssetsPending;if(force)return loadOwnerAssets(true);return}if(!force&&Date.now()<ownerAssetsExpires)return;ownerAssetsPending=(async()=>{const items=[];let cursor=null;for(let page=0;page<2;page++){const response=await fetch('/api/vpage/media'+(cursor?`?cursor=${encodeURIComponent(cursor)}`:''),{cache:'no-store'}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'โหลดคลังรูปไม่สำเร็จ');items.push(...(data.items||[]));cursor=data.pagination?.next_cursor;if(!cursor)break}ownerAssets=items;ownerAssetsExpires=Date.now()+30000;refreshOwnerAssetChoices()})();try{await ownerAssetsPending}finally{ownerAssetsPending=null}}
const listRow=(kind,item={})=>`<div class="vpage-item-row" data-item-row><div class="vpage-item-row-head"><b>${kind==='product'?'สินค้า':'ช่องทางติดต่อ'}</b><span><button type="button" data-move-item="-1" aria-label="เลื่อนขึ้น">↑</button><button type="button" data-move-item="1" aria-label="เลื่อนลง">↓</button><button type="button" data-remove-item>ลบ</button></span></div>${kind==='contact'?`<label>ประเภท<select data-item-field="contact_type"><option value="facebook"${item.contact_type==='facebook'?' selected':''}>Facebook</option><option value="line"${item.contact_type==='line'?' selected':''}>LINE</option></select></label>`:''}<label>ลิงก์ปลายทาง<input data-item-field="destination_url" type="text" maxlength="2048" required value="${esc(item.destination_url||'')}"></label>${mediaField('รูปประกอบ (ไม่บังคับ)',`<input data-item-field="image_url" data-media-url type="url" maxlength="2048" value="${esc(item.image_url||'')}">`)}</div>`;
const createStoredListRow=(kind,item={})=>`<div class="vpage-item-row" data-item-row><div class="vpage-item-row-head"><b>${kind==='product'?'สินค้า':'ช่องทางติดต่อ'}</b><span><button type="button" data-move-item="-1" aria-label="เลื่อนขึ้น">↑</button><button type="button" data-move-item="1" aria-label="เลื่อนลง">↓</button><button type="button" data-remove-item>ลบ</button></span></div>${kind==='contact'?`<label>ประเภท<select data-item-field="contact_type"><option value="facebook"${item.contact_type==='facebook'?' selected':''}>Facebook</option><option value="line"${item.contact_type==='line'?' selected':''}>LINE</option></select></label>`:''}<label>ลิงก์ปลายทาง<input data-item-field="destination_url" type="text" maxlength="2048" required value="${esc(item.destination_url||'')}"></label>${createMediaField('รูปประกอบ (ไม่บังคับ)',`<input data-item-field="image_url" data-media-url type="hidden" value="${esc(item.image_url||'')}">`)}</div>`;
