function refreshItemList(list){const rows=[...list.querySelectorAll('[data-item-row]')],count=list.querySelector('[data-item-count]');count.textContent=`${rows.length}/3`;list.querySelector('[data-add-item]').disabled=rows.length>=3;rows.forEach((row,index)=>{row.querySelector('[data-remove-item]').disabled=rows.length===1;row.querySelector('[data-move-item="-1"]').disabled=index===0;row.querySelector('[data-move-item="1"]').disabled=index===rows.length-1})}
