const templateCanvas=displayName=>`<section class="vpage-template-canvas" data-vpage-template-version="1" aria-label="ตัวอย่างโครงสร้างหน้า"><span class="vpage-template-label">ตัวอย่างหน้า SmartLinkPage</span><div data-template-slot="hero"><img alt="ตัวอย่างรูปสินค้า" hidden><span class="vpage-template-empty">รูปสินค้าหลัก</span></div><h4 data-template-name>${esc(displayName)}</h4><p data-template-slot="detail"></p><div class="vpage-template-video" data-template-video hidden>วิดีโอ YouTube จะแสดงตรงนี้</div><div data-template-slot="products"><span class="vpage-template-label">ลิงก์สินค้า</span><ul></ul></div><div data-template-slot="contacts"><span class="vpage-template-label">ช่องทางติดต่อ</span><ul></ul></div><span class="vpage-template-label" data-template-slot="background">รูปพื้นหลัง</span></section>`;
const previewUrl=input=>{const value=input?.dataset.previewUrl||input?.value.trim()||'';if(value.startsWith('blob:'))return value;if(/^\/api\/vpage\/media\/vpm_[a-f0-9]{32}$/.test(value))return value;try{const url=new URL(value);if(url.origin==='https://smartlinkpage.com'&&/^\/media\/vpm_[a-f0-9]{32}$/.test(url.pathname)&&!url.search&&!url.hash)return`/api/vpage/media/${url.pathname.split('/').at(-1)}`;return url.protocol==='https:'||(url.protocol==='http:'&&['127.0.0.1','localhost'].includes(url.hostname))?url.href:''}catch{return''}};
const createListRow=kind=>`<div class="vpage-item-row" data-item-row><div class="vpage-item-row-head"><b>${kind==='product'?'สินค้า':'ช่องทางติดต่อ'}</b><span><button type="button" data-move-item="-1" aria-label="เลื่อนขึ้น">↑</button><button type="button" data-move-item="1" aria-label="เลื่อนลง">↓</button><button type="button" data-remove-item>ลบ</button></span></div>${kind==='contact'?'<label>ประเภท<select data-item-field="contact_type"><option value="facebook">Facebook</option><option value="line">LINE</option></select></label>':''}<label>ลิงก์ปลายทาง<input data-item-field="destination_url" type="text" maxlength="2048" required placeholder="https://..."></label>${createMediaField('รูปประกอบ (ไม่บังคับ)','<input data-item-field="image_url" data-media-url type="hidden">')}</div>`;
