function openPayment(order){activeOrder=order;document.querySelector('#vpageOrderNo').textContent='เลขออเดอร์ '+order.orderNo;document.querySelector('#vpageOrderTotal').textContent=money(order.total);document.querySelector('#vpageBankName').textContent=order.bank?.bank_name||'-';document.querySelector('#vpageAccountName').textContent=order.bank?.account_name||'-';document.querySelector('#vpageAccountNumber').textContent=order.bank?.account_number||'-';document.querySelector('#vpageSlipMessage').textContent=order.status==='pending_review'?'ออเดอร์นี้มีสลิปแล้ว กำลังรอตรวจสอบ คุณสามารถส่งอีกครั้งเมื่อระบบแจ้งให้ลองใหม่':'';dialog.showModal()}
buy.onclick=async()=>{if(!offer)return;if(!currentUser){sessionStorage.setItem('vd_return_to','/vpage.html');location.href='/login.html';return}buy.disabled=true;try{const response=await fetch('/api/orders',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({productSlugs:[offer.slug],quantities:{[offer.slug]:1}})});const data=await response.json().catch(()=>({}));if(response.status===409&&data.code==='VPAGE_PENDING_ORDER'&&data.order?.id){openPayment(data.order);return}if(!response.ok)throw new Error(data.error||'สร้างคำสั่งซื้อไม่สำเร็จ');openPayment(data)}catch(error){alert(error.message)}finally{buy.disabled=false}};
document.querySelector('#closeVpagePayment').onclick=()=>dialog.close();
document.querySelector('#vpageSlipForm').onsubmit=async event=>{event.preventDefault();if(!activeOrder?.id)return;const button=event.currentTarget.querySelector('button[type="submit"]'),message=document.querySelector('#vpageSlipMessage');button.disabled=true;message.textContent='กำลังอัปโหลดสลิป…';try{const response=await fetch(`/api/orders/${activeOrder.id}/slip`,{method:'POST',body:new FormData(event.currentTarget)}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'ส่งสลิปไม่สำเร็จ');if(data.ok!==true||data.persisted!==true||!['pending_review','paid'].includes(data.order_status))throw new Error('ยืนยันการบันทึกสลิปไม่ได้ กรุณาลองส่งอีกครั้ง');const approved=data.auto_approved===true&&data.order_status==='paid';message.textContent=approved?'ชำระเงินสำเร็จ เครดิตเข้าบัญชีแล้ว':data.message||'รับสลิปแล้ว กำลังรอตรวจสอบ';if(approved)setTimeout(()=>location.reload(),900);else button.disabled=false}catch(error){message.textContent=error.message;button.disabled=false}};
loadMore.onclick=()=>loadCredits(false);createForm.inert=true;Promise.all([loadOffer(),loadAccount()]).catch(error=>{price.textContent=error.message;draftStatus.textContent='โหลดข้อมูลร่างไม่สำเร็จ กรุณาโหลดหน้าใหม่'});
